INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Audit immer eine finanzielle Überprüfung?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Prozesse oder IT-Systeme"}, {"text": "Ja", "correct": false, "because": "Nicht nur finanziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Audit?', 3, '[{"text": "Sicherstellung der Richtigkeit", "correct": true, "because": "Überprüft Daten/Prozesse"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Produktivität steigern", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zu einem Audit?', 5, '[{"text": "Prüfkriterien", "correct": true, "because": "Definiert Standards"}, {"text": "Dokumentation", "correct": true, "because": "Nachweis der Ergebnisse"}, {"text": "Marketingstrategie", "correct": false, "because": "Kein Prüfungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Audit kann extern sein. b) Es ist immer gesetzlich vorgeschrieben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht immer Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Audit?', 4, '[{"text": "Prüfungsstandards", "correct": false, "because": "Grundlage der Überprüfung"}, {"text": "Nachvollziehbarkeit", "correct": false, "because": "Sichert Ergebnisse"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Audit unabhängig sein muss?', 2, '[{"text": "Ja", "correct": true, "because": "Objektivität gewährleistet"}, {"text": "Nein", "correct": false, "because": "Unabhängigkeit oft gefordert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Audit prüft Finanzdaten?', 3, '[{"text": "Finanzaudit", "correct": true, "because": "Fokus auf Bilanzen"}, {"text": "IT-Audit", "correct": false, "because": "Systemprüfung"}, {"text": "Prozessaudit", "correct": false, "because": "Ablaufprüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zu einem umfassenden Audit?', 5, '[{"text": "Risikobeurteilung", "correct": true, "because": "Identifiziert Schwachstellen"}, {"text": "Prüfungsbericht", "correct": true, "because": "Dokumentiert Ergebnisse"}, {"text": "Produktwerbung", "correct": false, "because": "Kein Prüfungsaspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Audits sichern Compliance. b) Sie sind immer zeitaufwendig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zeit variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Audit unwichtig?', 4, '[{"text": "Prüfungsplan", "correct": false, "because": "Strukturiert Vorgehen"}, {"text": "Dokumentation", "correct": false, "because": "Nachweis nötig"}, {"text": "Bürofarben", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Audit extern sein?', 2, '[{"text": "Nein", "correct": true, "because": "Intern möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Audit?', 4, '[{"text": "Transparenz", "correct": true, "because": "Klarheit über Prozesse"}, {"text": "Risikominimierung", "correct": true, "because": "Fehler erkennen"}, {"text": "Schnellere Abläufe", "correct": false, "because": "Nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Audits immer teuer sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten variieren"}, {"text": "Ja", "correct": false, "because": "Abhängig von Umfang"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Audit?', 3, '[{"text": "Objektivität", "correct": true, "because": "Sichert Fairness"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität wichtiger"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Audit kann Schwachstellen aufdecken. b) Es ist nur für Finanzen relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht nur Finanzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat ein schlechtes Audit?', 5, '[{"text": "Ungenaue Ergebnisse", "correct": true, "because": "Fehlende Standards"}, {"text": "Vertrauensverlust", "correct": true, "because": "Mangelnde Objektivität"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Audit unwichtig?', 3, '[{"text": "Prüfungsstandards", "correct": false, "because": "Grundlage"}, {"text": "Berichterstattung", "correct": false, "because": "Ergebnisse wichtig"}, {"text": "Dekoration", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Audit intern durchgeführt werden?', 3, '[{"text": "Ja", "correct": true, "because": "Interne Teams möglich"}, {"text": "Nein", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Audit regelmäßig sein muss?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anforderungen"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art wähle ich für IT-Systeme?', 4, '[{"text": "IT-Audit", "correct": true, "because": "Fokus auf Systeme"}, {"text": "Finanzaudit", "correct": false, "because": "Finanzprüfung"}, {"text": "Marketingaudit", "correct": false, "because": "Anderer Bereich"}]');
